// Also make curated prose available to t()/localizedText() when a component
// receives only the source string rather than the complete fish record.
for (const fish of curatedFish) {
  const translations = fishTranslations[fish.scientific.toLowerCase()];
  for (const [field, translated] of Object.entries(translations ?? {})) {
    const source = (fish as Record<string, unknown>)[field];
    if (typeof source === "string") dataMessages[source] = translated;
  }
}
